# -*- coding: utf-8 -*-
"""docs/2.6-美术风格指南.docx —— 按 game-docs-and-sheets-inventory.md 2.6 写。

清单要求：参考图（3~5 张，标「学它哪一点」）/ 色板（十六进制）/ 字号层级（最大 3 级）/
图形规范（圆角、阴影、间距单位）/ 禁止项。
事实来源：src/ui/style.css 的 :root 与组件规则、shots/ 截图。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "2.6-美术风格指南.docx")


def main():
    doc = k.new_doc("2.6 美术风格指南 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器 · 美术风格",
        "色板 · 字号 · 间距 · 组件规矩 · 禁止项 · v0.1 · 2026-11-04",
    )

    k.note(
        doc,
        "这个游戏没有美术资源：0 张位图、0 段音频、0 个图标，全靠 CSS。所以「美术风格」= **颜色、字号、间距、组件** 四条规矩。"
        "所有值取自 `src/ui/style.css` 的 `:root` 与组件定义；改风格先改这里，再改 CSS。",
    )

    k.h1(doc, "一", "一句话风格")
    k.para(
        doc,
        "**深色终端感 + 等宽数字 + 只用彩色标涨跌。** 界面要像一块看比赛的记分牌：安静，数字醒目，"
        "彩色只出现在「涨了」「跌了」「选中了」这三件事上。",
    )
    k.table(
        doc,
        ["原则", "具体表现", "反例"],
        [
            ["数字优先", "玩家看的是六维、钱、名次；文字是配角", "大段说明文字压在数值上面"],
            ["一个焦点", "一屏只有一个主角（当周 vs 事件 vs 结局）", "每块都用同样的框和同样的字号"],
            ["彩色要省", "绿=涨/赢，红=跌/输，蓝=选中/进度，黄=警示", "给每个属性和每个按钮上不同颜色"],
        ],
        [2.6, 8.4, 5.0],
        size=9,
    )

    k.h1(doc, "二", "色板（全部十六进制，不许新增）")
