        doc,
        ["变量", "色值", "用在哪", "不用在哪"],
        [
            ["--bg", "#0d1117", "页面底色", "—"],
            ["--panel", "#161b22", "卡片、浮层底", "—"],
            ["--panel-2", "#1c2128", "卡片里的次级块（行动格、商店行）", "整屏背景"],
            ["--line", "#30363d", "1px 描边与分隔线", "文字"],
            ["--fg", "#e6edf3", "正文、数字", "次要说明"],
            ["--muted", "#8b949e", "辅助文字、单位、空态", "主数值"],
            ["--accent", "#58a6ff", "进度条、选中页签、可点链接", "涨跌数字"],
            ["--good", "#3fb950", "涨、赢、正向差额", "装饰"],
            ["--bad", "#f85149", "跌、输、负向差额", "装饰"],
            ["--warn", "#d29922", "警示（伤病、体力见底）", "普通信息"],
        ],
        [2.8, 2.6, 8.0, 7.8],
        size=8.5,
        caption="表 2-1　共 10 个颜色，全部已在 style.css 的 :root 里；需要新色先在这里加一行，不许在组件里写死",
